from fractions import Fraction
from itertools import combinations

def arithmetic_mean(x, y):
    return (x + y) / 2

def harmonic_mean(x, y):
    # HM = 2xy / (x+y)
    return (2 * x * y) / (x + y)

def solve_ratio_general(m, n, max_steps=10):
    # Initial set of numbers: {m/n, n/m}
    initial_set = {Fraction(m, n), Fraction(n, m)}

    if Fraction(1) in initial_set:
        return True

    # BFS/Queue stores tuples: (current_set_of_numbers, current_step)
    queue = [(initial_set, 0)]

    # Use a tuple representation of the sorted set for hashing
    visited_states = {tuple(sorted(initial_set))}

    while queue:
        current_set, step = queue.pop(0)

        if step >= max_steps:
            continue

        numbers = list(current_set)
        pairs = list(combinations(numbers, 2))

        for x, y in pairs:

            # 1. Arithmetic Mean (AM)
            am_val = arithmetic_mean(x, y)

            if am_val == 1:
                return True

            new_set_am = current_set.union({am_val})
            new_set_am_tuple = tuple(sorted(new_set_am))

            if new_set_am_tuple not in visited_states:
                visited_states.add(new_set_am_tuple)
                queue.append((new_set_am, step + 1))

            # 2. Harmonic Mean (HM)
            hm_val = harmonic_mean(x, y)

            if hm_val == 1:
                return True

            new_set_hm = current_set.union({hm_val})
            new_set_hm_tuple = tuple(sorted(new_set_hm))

            if new_set_hm_tuple not in visited_states:
                visited_states.add(new_set_hm_tuple)
                queue.append((new_set_hm, step + 1))

    return False

# Test the maximal candidate based on the structural hypothesis: m+n = 2999
m_max = 2999
n_max = 1

print(f"--- Testing Maximal Candidate ({m_max}, {n_max}) ---")
success_max = solve_ratio_general(m_max, n_max, max_steps=10)
print(f"Ratio ({m_max}, {n_max}): {'SUCCESS' if success_max else 'FAILURE'}")
